def augment(profiles):
    for profile in profiles:
        key = profile['id'].removeprefix('ck-')
        if key in CONTRACTS:
            profile['content'] += '\nContrato comercial específico:\n' + COMMON + CONTRACTS[key][2] + '\n'
        elif key == 'revenue-orchestrator':
            profile['content'] += '\n' + COMMON + '''Você persiste os candidatos estruturados recebidos dos workers com sales.py ingest --file <arquivo>. Somente registros qualificados recebem SDR. Não delegue cada empresa como nova sessão: lote pequeno, até 5 empresas por ciclo. Rotas: lead-pipeline (descoberta → enriquecimento → qualificação → SDR → auditoria), demand-pipeline (radar de demanda → enriquecimento → qualificação → SDR → auditoria), replies (triagem de respostas → followup → auditoria), referrals semanal (indicação → auditoria), partnerships semanal (parcerias → auditoria). Meça qualificados, envios, respostas, reuniões, vendas e caixa por origem; não meça projetos ou issues. Não precisa de proposta antes de haver resposta. Rota proposal: proposta → followup → auditoria, somente com entradas elegíveis. Leia sales.py list antes de cada ciclo e execute sales.py report ao terminar, inclusive quando não encontrar candidatos. Nenhum envio externo. Não escreva estágios sent/replied/meeting/won/paid sem evidência operacional legítima. O dono registra envios, reuniões, recusas e opt-out com python3 ~/.copilot/chronokairo/sales.py mark --domain <dominio> --stage sent --channel <canal>; lembre esse comando no documento Comercial do Desktop. Venda e pagamento exigem documento via sales.py event. Em falha de modelo registre blocked, preservando trabalho existente.\n'''
    return profiles

def route_instruction(key):
    if key not in {'lead-pipeline','demand-pipeline','replies','referrals','partnerships','proposal','new-business','company-cycle','daily-report'}: return ''
    text = '\nLeia ~/.copilot/chronokairo/sales-playbook.md. Aquisição exclui Audiomed e qualquer outro cliente existente; não conte manutenção como cliente novo. Separe candidato, qualificado, mensagem pronta, envio, resposta, reunião, contrato e recebimento. Antes de trabalhar consulte python3 ~/.copilot/chronokairo/sales.py list; no fim execute sales.py report. Preserve métricas desconhecidas, não substitua por issues ou projetos.\n'
    if key == 'demand-pipeline':
        text += 'Execute radar de demanda→enriquecimento→qualificação→SDR→auditoria com até 5 sinais declarados e recentes, em inglês por padrão. Coordenador grava JSON com source_type=demand por sales.py ingest. Nenhum envio externo.\n'
    if key == 'replies':
        text += 'Execute sales_chat.py pull para as respostas novas do canal #comercial-leads do Chronokairo Chat. Após classificação, registre replied/opt_out/rejected por sales.py event com a evidência salva e publique triagem, réplica e follow-ups na thread da mensagem com sales_chat.py post --reply-to. Chat não configurado: use a entrada provisória do Desktop retornada pelo pull e grave a triagem em Desktop/Chronokairo/Comercial-Respostas-<data>.md. Sem mensagens novas, encerre sem inventar respostas. Publicar no canal interno não é envio ao prospect.\n'
    if key == 'referrals':
        text += 'Prepare o pedido de indicação e o texto de apresentação para clientes existentes, respeitando um pedido por trimestre. Registre indicados com source_type=referral e referred_by. Nenhum envio externo.\n'
    if key == 'partnerships':
        text += 'Execute parcerias→auditoria com até 5 parceiros de canal com fonte pública. Coordenador grava JSON com source_type=partner por sales.py ingest e entrega propostas de parceria no Desktop. Nenhum envio externo.\n'
    if key == 'lead-pipeline':
        text += 'Execute descoberta→enriquecimento→qualificação→SDR→auditoria em lote de até 5 empresas, entregue fontes/canais oficiais e rascunhos no Desktop. Coordenador grava JSON por sales.py ingest. Nenhum envio externo.\n'
    if key == 'new-business':
        text += 'Antes de requirements/spec/bootstrap, exija demanda externa confirmada ou encomenda real. Se houver apenas hipótese comercial, não execute essas etapas: prepare descoberta/oferta comercial e registre ausência de comprador. Audiomed é entrega existente, não aquisição.\n'
    return text
